import{z as s,x as i,o as n,c as B,q as r,j as o,D as e,d as l,s as E,S as A}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"最近公共祖先","description":"","frontmatter":{"title":"最近公共祖先","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lca.md","filePath":"cs/lca.md","lastUpdated":1791413859000}'),d={name:"cs/lca.md"};function p(C,a,c,h,m,_){const t=i("Mermaid");return n(),B("div",null,[a[2]||(a[2]=r('<h1 id="最近公共祖先" tabindex="-1">最近公共祖先 <a class="header-anchor" href="#最近公共祖先" aria-label="Permalink to &quot;最近公共祖先&quot;">​</a></h1><div class="epigraph"><p>树上两点的最近公共祖先是同时盖住二者的最深顶点；离线并查集或在线倍增、欧拉序加 RMQ，都能答。</p><footer>—— 据 Tarjan, Applications of Path Compression on Balanced Trees, 1979；Harel and Tarjan, Fast Algorithms for Finding Nearest Common Ancestors, 1984；Bender and Farach-Colton, The LCA Problem Revisited, 2000 整理</footer></div><p>上一课<a href="/cs/hamiltonian-tsp-exact">哈密顿与 TSP 精确解</a>在一般图上指数。本课把图收成<strong>树</strong>（或有根树）：两点之间唯一路径，询问最近公共祖先（LCA）。不重做子集 DP。缺口是查询结构——离线一次扫完，或预处理后在线。后课倍增把同一技巧用到路径聚合与树上差分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有根树，\\(lca(u,v)\\) 为 \\(u\\)、\\(v\\) 的公共祖先中深度最大者。路径 \\(u\\)–\\(v\\) 就是 \\(u\\) 到 \\(lca\\) 再下到 \\(v\\)。朴素双指针上跳 \\(O(n)\\) 每次。缺口是更快：离线 \\(m\\) 次询问，或预处理后 \\(O(1)\\)/\\(O(\\log n)\\)。</p><p>Tarjan 离线：DFS 时用并查集维护「已处理子树的代表」；回溯时把询问另一端已访的点与当前点求 LCA。一次 DFS + 几乎 \\(O(n+m)\\)。在线：预处理深度与父，或欧拉序（进出把树摊成序列，LCA 变成序列上的 RMQ）。</p><p><span class="marginnote">术语翻译：离线/在线说的是询问何时可知——离线 = 所有询问提前拿全，一次 DFS 走完顺便把每条都答掉（Tarjan 并查集）；在线 = 询问随时插进来，必须先花预处理时间备好一张随时可查的表（倍增、RMQ）。竞赛读入方式常决定选哪族算法。</span></p><h3 id="rmq-不是另一道题" tabindex="-1">RMQ 不是另一道题 <a class="header-anchor" href="#rmq-不是另一道题" aria-label="Permalink to &quot;RMQ 不是另一道题&quot;">​</a></h3><p>欧拉序上相邻深度差 \\(1\\)，\\(\\pm 1\\) RMQ 可 \\(O(n)\\) 预处理、\\(O(1)\\) 查询（Bender–Farach-Colton）。一般 RMQ 稀疏表 \\(O(n\\log n)\\)–\\(O(1)\\)。本课认「LCA \\(\\leftrightarrow\\) RMQ」，不把稀疏表写成另一课程。</p><p><span class="marginnote">Tarjan 1979 离线并查集。Harel–Tarjan 1984 讨论在线线性预处理。Bender–Farach-Colton 2000 把 \\(\\pm 1\\) RMQ 写清楚。后课树上倍增是同一父指针的对数张表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>小 \\(n\\) 可倍增：<code>fa[k][u]</code> 为 \\(u\\) 的 \\(2^k\\) 祖先，预处理 \\(O(n\\log n)\\)，查询先对齐深度再一起跳，\\(O(\\log n)\\)。离线用并查集。需要常数查询再用欧拉序 RMQ。</p>',12)),(n(),o(A,null,{default:e(()=>[E(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%9C%89%E6%A0%B9%E6%A0%91%22%5D%20--%3E%20OFF%5B%22%E7%A6%BB%E7%BA%BF%EF%BC%9ADFS%20%2B%20%E5%B9%B6%E6%9F%A5%E9%9B%86%22%5D%0A%20%20T%20--%3E%20BIN%5B%22%E5%9C%A8%E7%BA%BF%EF%BC%9A%E5%80%8D%E5%A2%9E%20fa%5Bk%5D%5Bu%5D%22%5D%0A%20%20T%20--%3E%20RMQ%5B%22%E6%AC%A7%E6%8B%89%E5%BA%8F%20%2B%20RMQ%22%5D%0A%20%20OFF%20--%3E%20LCA%5B%22lca(u%2Cv)%22%5D%0A%20%20BIN%20--%3E%20LCA%0A%20%20RMQ%20--%3E%20LCA%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>森林：先找根；不同树无 LCA，或虚根。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>括号序/欧拉序：第一次访问时刻之间的点，深度最小者即 LCA（更精确：欧拉序区间内深度最小的顶点）。倍增：深度差的二进制分解是在链上跳，与<a href="/cs/fast-exponentiation">二进制快速幂</a>同一「倍增」念头，后课才把矩阵幂展开；本课只跳父指针。</p><p><span class="marginnote">数字实例：两结点深度差为 13 = 8+4+1，即按 \\(2^3, 2^2, 2^0\\) 三步跳平；\\(n=10^5\\) 的树倍增表只需 \\(\\lceil \\log_2 n \\rceil = 17\\) 层，任何一次查询至多跳 \\(2\\times 17\\) 次——这就是「预处理 \\(O(n\\log n)\\)、查询 \\(O(\\log n)\\)」里那些对数的真身。</span></p><p><span class="marginnote">直觉类比：欧拉序像把树「压扁」成一份巡逻足迹——DFS 每次经过一个点就记一笔。两个点的 LCA，就是足迹里这两点之间海拔（深度）最低的那个点：想上树顶必须先经过它。LCA 于是变成「区间最小值」，RMQ 的全部机器都能搬过来用。</span></p>',5)),(n(),o(A,null,{default:e(()=>[E(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%AF%A2%E9%97%AE%20lca(u%2C%20v)%22%5D%20--%3E%20C1%7B%22u%20%E4%B8%8E%20v%20%E6%B7%B1%E5%BA%A6%E7%9B%B8%E5%90%8C%3F%22%7D%0A%20%20C1%20--%3E%7C%22%E5%90%A6%22%7C%20UP%5B%22%E8%BE%83%E6%B7%B1%E8%80%85%E6%8C%89%E6%B7%B1%E5%BA%A6%E5%B7%AE%E7%9A%84%E4%BA%8C%E8%BF%9B%E5%88%B6%E9%80%90%E4%BD%8D%E4%B8%8A%E8%B7%B3%22%5D%0A%20%20UP%20--%3E%20C2%7B%22%E8%B7%B3%E5%B9%B3%E5%90%8E%20u%20%3D%3D%20v%3F%22%7D%0A%20%20C2%20--%3E%7C%22%E6%98%AF%22%7C%20A1%5B%22u%20%E6%9C%AC%E8%BA%AB%E5%B0%B1%E6%98%AF%20LCA%22%5D%0A%20%20C2%20--%3E%7C%22%E5%90%A6%22%7C%20C3%5B%22%E4%B8%A4%E6%8C%87%E9%92%88%E4%BB%8E%E5%A4%A7%20k%20%E5%88%B0%E5%B0%8F%E5%90%8C%E6%AD%A5%E4%B8%8A%E8%B7%B3%22%5D%0A%20%20C3%20--%3E%20A2%5B%22%E9%A6%96%E6%AC%A1%E7%88%B6%E6%8C%87%E9%92%88%E7%9B%B8%E5%90%8C%E7%9A%84%E5%89%8D%E4%B8%80%E6%AD%A5%3A%20%E5%8D%B3%20LCA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>这张图回答的问题：一次倍增查询内部到底怎么跳。两步走——先把深者按深度差的二进制对齐到同层，若还没相遇，就让两者同速按 \\(2^k\\) 往上试跳；每层只决定「跳或不跳」一位，所以查询是纯对数次查表。</p><p>不要在有环图上定义 LCA：最近公共祖先依赖树（或 DAG 上要另定义，本课不写）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写重链剖分（下一课的下一课）、不写点分治。动态加点、换根在线是另一模型。后课默认：树上两点路径经过 LCA；倍增表是标准预处理。下一课把倍增接到路径和与树上差分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LCA 是两点路径的最高点；树上路径唯一。</li><li>离线并查集；在线倍增或欧拉序 RMQ。</li><li>一般图的「祖先」没有这一定义。</li><li>出处：Tarjan, 1979；Harel and Tarjan, 1984；Bender and Farach-Colton, 2000。</li></ul>',6))])}const T=s(d,[["render",p]]);export{D as __pageData,T as default};
